            "minLength": 5,
            "maxLength": 96,
            "pattern": "^[\\+\\w-]{5,96}$"
        },
        "email": {
            "description": "The email address for the account.",
            "type": "string",
            "pattern": "^\\S+@\\S+$"
        },
        "customer": {
            "description": "The platform's customer.",
            "type": "string",
            "minLength": 3,
            "maxLength": 96
        }
    },
    "required": [
        "identifier",
        "email",
        "customer"
    ]
}

